20→export enum VisitorArchetype {
21→  FAST_SCANNER = 'fast_scanner',           // Quick scrolling, minimal interaction
22→  TECHNICAL_EXPLORER = 'technical_explorer', // Clicks details, slower scroll
23→  CASUAL_BROWSER = 'casual_browser',        // Default/everything else
24→  UNKNOWN = 'unknown',                      // Not enough data yet
25→}
