 5→/**
 6→ * SCROLL RESET - Ensures page starts at top
 7→ *
 8→ * Forces scroll to top on mount, ensuring users land on the
 9→ * hero reel at the topmost edge of the page.
10→ */
11→export function ScrollReset() {
12→  useEffect(() => {
13→    // Immediate scroll to top
14→    window.scrollTo(0, 0);
15→
16→    // Also reset after a brief delay to handle any layout shifts
17→    const timer = setTimeout(() => {
